1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.dto.ItemRequest;
4	import com.loja.checkout.dto.PedidoRequest;
5	import com.loja.checkout.dto.ResumoResponse;
6	import com.loja.checkout.exception.CodigoErro;
7	import com.loja.checkout.exception.PedidoRecusadoException;
8	import com.loja.checkout.model.ContextoCupom;
9	import com.loja.checkout.model.Cupom;
10	import com.loja.checkout.model.Dinheiro;
11	import com.loja.checkout.model.FormaPagamento;
12	import com.loja.checkout.model.ModalidadeEntrega;
13	import com.loja.checkout.model.NivelClube;
14	import com.loja.checkout.model.Regiao;
15	import com.loja.checkout.model.ResultadoPagamento;
16	import org.springframework.stereotype.Service;
17	
18	import java.math.BigDecimal;
19	import java.util.List;
20	
21	@Service
22	public class ResumoCompraService {
23	
24	    public ResumoResponse calcular(PedidoRequest pedido) {
25	        validarItens(pedido.itens());
26	        NivelClube nivelClube = parseNivelClube(pedido.nivelClube());
27	        Regiao regiao = parseRegiao(pedido.regiao());
28	        ModalidadeEntrega modalidade = parseModalidade(pedido.modalidadeEntrega());
29	
30	        BigDecimal subtotalProdutos = calcularSubtotal(pedido.itens());
31	        BigDecimal pesoTotalKg = calcularPesoTotal(pedido.itens());
32	
33	        if (!modalidade.disponivel(pesoTotalKg)) {
34	            throw new PedidoRecusadoException(CodigoErro.MODALIDADE_INDISPONIVEL);
35	        }
36	
37	        BigDecimal frete = modalidade.calcularFrete(pesoTotalKg);
38	        if (nivelClube.freteGratis()) {
39	            frete = Dinheiro.arredondar(BigDecimal.ZERO);
40	        }
41	
42	        Cupom cupom = parseCupom(pedido.cupom());
43	        BigDecimal descontoCupom = Dinheiro.arredondar(BigDecimal.ZERO);
44	        if (cupom != null) {
45	            ContextoCupom contextoCupom = new ContextoCupom(subtotalProdutos, frete, pedido.itens());
46	            if (!cupom.aplicavel(contextoCupom)) {
47	                throw new PedidoRecusadoException(CodigoErro.CUPOM_NAO_APLICAVEL);
48	            }
49	            descontoCupom = cupom.calcularDesconto(contextoCupom);
50	        }
51	
52	        BigDecimal seguro = regiao.calcularSeguro(subtotalProdutos);
53	
54	        BigDecimal totalPedido = Dinheiro.arredondar(
55	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
56	
57	        FormaPagamento formaPagamento = parseFormaPagamento(pedido.formaPagamento());
58	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
59	        if (!formaPagamento.parcelasValidas(parcelas)) {
60	            throw new PedidoRecusadoException(CodigoErro.PARCELAMENTO_INVALIDO);
61	        }
62	        if (!formaPagamento.disponivel(totalPedido)) {
63	            throw new PedidoRecusadoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
64	        }
65	
66	        ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
67	
68	        BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
69	        boolean brinde = nivelClube.temBrinde(subtotalProdutos);
70	
71	        return new ResumoResponse(
72	                subtotalProdutos,
73	                descontoCupom,
74	                frete,
75	                modalidade.prazoEntregaDias(),
76	                seguro,
77	                resultadoPagamento.ajuste(),
78	                resultadoPagamento.totalFinal(),
79	                parcelas,
80	                resultadoPagamento.valorParcela(),
81	                creditoProximaCompra,
82	                brinde
83	        );
84	    }
85	
86	    private void validarItens(List<ItemRequest> itens) {
87	        if (itens == null || itens.isEmpty()) {
88	            throw new PedidoRecusadoException(CodigoErro.PEDIDO_INVALIDO);
89	        }
90	        for (ItemRequest item : itens) {
91	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
92	                    || item.quantidade() == null || item.quantidade() <= 0
93	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
94	                throw new PedidoRecusadoException(CodigoErro.PEDIDO_INVALIDO);
95	            }
96	        }
97	    }
98	
99	    private NivelClube parseNivelClube(String valor) {
100	        return parseEnum(valor, NivelClube.class, CodigoErro.NIVEL_CLUBE_INVALIDO);
101	    }
102	
103	    private Regiao parseRegiao(String valor) {
104	        return parseEnum(valor, Regiao.class, CodigoErro.REGIAO_INVALIDA);
105	    }
106	
107	    private ModalidadeEntrega parseModalidade(String valor) {
108	        return parseEnum(valor, ModalidadeEntrega.class, CodigoErro.MODALIDADE_INVALIDA);
109	    }
110	
111	    private FormaPagamento parseFormaPagamento(String valor) {
112	        return parseEnum(valor, FormaPagamento.class, CodigoErro.FORMA_PAGAMENTO_INVALIDA);
113	    }
114	
115	    private Cupom parseCupom(String valor) {
116	        if (valor == null || valor.isBlank()) {
117	            return null;
118	        }
119	        try {
120	            return Cupom.valueOf(valor);
121	        } catch (IllegalArgumentException e) {
122	            throw new PedidoRecusadoException(CodigoErro.CUPOM_INVALIDO);
123	        }
124	    }
125	
126	    private <E extends Enum<E>> E parseEnum(String valor, Class<E> tipo, CodigoErro codigoErro) {
127	        if (valor == null || valor.isBlank()) {
128	            throw new PedidoRecusadoException(codigoErro);
129	        }
130	        try {
131	            return Enum.valueOf(tipo, valor);
132	        } catch (IllegalArgumentException e) {
133	            throw new PedidoRecusadoException(codigoErro);
134	        }
135	    }
136	
137	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
138	        BigDecimal subtotal = BigDecimal.ZERO;
139	        for (ItemRequest item : itens) {
140	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
141	        }
142	        return Dinheiro.arredondar(subtotal);
143	    }
144	
145	    private BigDecimal calcularPesoTotal(List<ItemRequest> itens) {
146	        BigDecimal pesoTotal = BigDecimal.ZERO;
147	        for (ItemRequest item : itens) {
148	            pesoTotal = pesoTotal.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
149	        }
150	        return pesoTotal;
151	    }
152	}
