57	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
58	            if (parcelas <= 3) {
59	                BigDecimal valorParcela = Dinheiro.arredondar(
60	                        totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128));
61	                return new ResultadoPagamento(BigDecimal.ZERO.setScale(2), totalPedido, valorParcela);
62	            }
63	            BigDecimal fatorMensal = BigDecimal.ONE.add(CARTAO_TAXA_JUROS_MENSAL);
64	            BigDecimal fatorElevado = fatorMensal.pow(parcelas, MathContext.DECIMAL128);
65	            BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fatorElevado, MathContext.DECIMAL128));
66	            BigDecimal valorParcela = Dinheiro.arredondar(
67	                    totalPedido.multiply(CARTAO_TAXA_JUROS_MENSAL).divide(denominador, MathContext.DECIMAL128));
68	            BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
69	            BigDecimal ajuste = totalFinal.subtract(totalPedido);
70	            return new ResultadoPagamento(ajuste, totalFinal, valorParcela);
71	        }
72	    };
