74	    private static final BigDecimal PIX_PERCENTUAL_DESCONTO = new BigDecimal("0.05");
75	    private static final BigDecimal BOLETO_LIMITE_TOTAL = new BigDecimal("1000.00");
76	    private static final BigDecimal BOLETO_TARIFA = new BigDecimal("3.49");
77	    private static final BigDecimal CARTAO_TAXA_JUROS_MENSAL = new BigDecimal("0.0199");
