            BigDecimal ajuste = totalFinal.subtract(totalPedido);
            return new ResultadoPagamento(ajuste, totalFinal, valorParcela);
        }
    };

    private static final BigDecimal PIX_PERCENTUAL_DESCONTO = new BigDecimal("0.05");
